FUNCTION_BLOCK FB_Semiconductor_SingleWaferWetClean
VAR_INPUT
    (* Digital Supervisory Controls & Safety Interlocks *)
    bEnable                 : BOOL;         (* Master supervisory enable signal *)
    bEmergencyStopRelayOk   : BOOL;         (* Dual-channel safety relay healthy [SIL3 / PLe] *)
    bStartCycle             : BOOL;         (* Recipe execution start command pulse *)
    bAbortCycle             : BOOL;         (* Asynchronous emergency process abort pulse *)
    iRecipeId               : INT;          (* Recipe selector: 1=Standard RCA, 2=DHF Strip, 3=Cu Post-CMP *)

    (* 2oo3 Triple Modular Redundancy (TMR) - Wafer Chuck Vacuum Sensors [mbar] *)
    rChuckVac1_mbar         : REAL;         (* Vacuum transducer 1 at Bernoulli chuck pin center [-1000.0 .. 0.0 mbar] *)
    rChuckVac2_mbar         : REAL;         (* Vacuum transducer 2 at Bernoulli chuck pin intermediate [-1000.0 .. 0.0 mbar] *)
    rChuckVac3_mbar         : REAL;         (* Vacuum transducer 3 at Bernoulli chuck pin outer ring [-1000.0 .. 0.0 mbar] *)

    (* 2oo3 Triple Modular Redundancy (TMR) - Chuck Spindle Tachometers [rpm] *)
    rChuckSpeed1_rpm        : REAL;         (* Spindle direct-drive optical incremental encoder 1 [0.0 .. 5000.0 rpm] *)
    rChuckSpeed2_rpm        : REAL;         (* Spindle direct-drive optical incremental encoder 2 [0.0 .. 5000.0 rpm] *)
    rChuckSpeed3_rpm        : REAL;         (* Spindle motor resolver / magnetic hall sensor 3 [0.0 .. 5000.0 rpm] *)

    (* 2oo3 Triple Modular Redundancy (TMR) - Inline Chemical Delivery Temperatures [deg C] *)
    rChemTemp1_degC         : REAL;         (* Inline PFA manifold dual-element RTD sensor 1 [10.0 .. 95.0 deg C] *)
    rChemTemp2_degC         : REAL;         (* Inline PFA manifold dual-element RTD sensor 2 [10.0 .. 95.0 deg C] *)
    rChemTemp3_degC         : REAL;         (* Inline PFA manifold secondary reference RTD 3 [10.0 .. 95.0 deg C] *)

    (* Process Media Flow Transducers [mL/min], Gas Flow [sccm], Exhaust [Pa], Motion [mm/s], [mm] *)
    rFlowSC1_mLmin          : REAL;         (* SC1 (NH4OH/H2O2/DIW) Coriolis mass flow rate [0.0 .. 3000.0 mL/min] *)
    rFlowDHF_mLmin          : REAL;         (* DHF (Dilute Hydrofluoric Acid) ultrasonic flow [0.0 .. 2500.0 mL/min] *)
    rFlowSC2_mLmin          : REAL;         (* SC2 (HCl/H2O2/DIW) ultrasonic flow [0.0 .. 2500.0 mL/min] *)
    rFlowUPW_mLmin          : REAL;         (* Ultra-Pure Water rinse Coriolis flow rate [0.0 .. 6000.0 mL/min] *)
    rFlowIPAN2_sccm         : REAL;         (* Marangoni IPA vapor carrier N2 mass flow [0.0 .. 10000.0 sccm] *)
    rChamberExhaust_Pa      : REAL;         (* Cleanroom cup differential static exhaust pressure [-250.0 .. 0.0 Pa] *)
    rChuckVibration_mms     : REAL;         (* Spindle bearing 3-axis accelerometer vibration [0.0 .. 25.0 mm/s RMS] *)
    rArmRadialPos_mm        : REAL;         (* Dispense arm absolute linear magnetostrictive encoder [-40.0 .. 180.0 mm] *)
END_VAR

VAR_OUTPUT
    (* SEMI Operational Status & High-Level Telemetry *)
    bSystemReady            : BOOL;         (* Ready for wafer transfer robot handoff *)
    bCycleRunning           : BOOL;         (* Recipe execution currently in active progress *)
    bCycleComplete          : BOOL;         (* Recipe sequence finished with zero interlock excursions *)
    bAlarmActive            : BOOL;         (* Master safety trip / critical abort state active *)
    bWarningActive          : BOOL;         (* Sensor disagreement or non-critical maintenance warning *)
    wStatusWord             : WORD;         (* SEMI E30 GEM 16-bit Equipment Status Register *)
    wAlarmWord1             : WORD;         (* Interlock and Sensor Failure Bitmask *)
    wAlarmWord2             : WORD;         (* Process Variable Tolerance & Actuator Excursion Bitmask *)
    wSensorHealthMask       : WORD;         (* 2oo3 Instrumentation Degraded Channel Identification Register *)

    (* Motion Control Trajectory Setpoints [rpm], [Nm], [mm], [mm/s] *)
    rChuckSpeedSetpt_rpm    : REAL;         (* Chuck servo spindle velocity command [0.0 .. 4500.0 rpm] *)
    rChuckTorqueLimit_Nm    : REAL;         (* Dynamically scheduled motor drive torque boundary [0.0 .. 25.0 Nm] *)
    rArmPosSetpoint_mm      : REAL;         (* Linear arm servo absolute radial target [0.0 .. 160.0 mm] *)
    rArmVelSetpoint_mms     : REAL;         (* Linear arm dynamic feed velocity profile [0.0 .. 350.0 mm/s] *)

    (* Chemical Manifold Fluid & Energy Control *)
    bValveSC1_Cmd           : BOOL;         (* SC1 pneumatic dispense valve pilot command *)
    bValveDHF_Cmd           : BOOL;         (* DHF pneumatic dispense valve pilot command *)
    bValveSC2_Cmd           : BOOL;         (* SC2 pneumatic dispense valve pilot command *)
    bValveUPW_Cmd           : BOOL;         (* UPW rinse high-purity diaphragm valve pilot command *)
    bValveIPAVapor_Cmd      : BOOL;         (* Marangoni IPA vapor generation injection solenoid *)
    bValveChuckVac_Cmd      : BOOL;         (* Wafer chuck Bernoulli vacuum grip clamping valve *)
    bValveChamberN2_Cmd     : BOOL;         (* Chamber ionization curtain and spin-dry N2 purge solenoid *)
    bMegasonicEnable        : BOOL;         (* RF power generator excitation enable for megasonic nozzle *)
    rMegasonicPower_W       : REAL;         (* Megasonic acoustic power level command [0.0 .. 150.0 W] *)
    rCurrentStepTime_s      : REAL;         (* Elapsed duration within current process phase [s] *)
END_VAR

VAR
    (* Sequencer State Enumeration *)
    iStep                   : INT := 0;     (* Sequencer finite state index *)
    iPrevStep               : INT := -1;    (* Previous cycle step tracking for transition edge *)
    iTargetStep             : INT := 0;     (* Requested target step for deterministic sequencing *)

    (* 2oo3 TMR Voting Logic Internal Variables *)
    rVotedChuckVac_mbar     : REAL := 0.0;  (* Validated median/mean vacuum pressure [mbar] *)
    rVotedChuckSpeed_rpm    : REAL := 0.0;  (* Validated median/mean chuck spindle rotational velocity [rpm] *)
    rVotedChemTemp_degC     : REAL := 21.0; (* Validated median/mean chemical process temperature [deg C] *)

    bVacSensor1_Fault       : BOOL := FALSE;
    bVacSensor2_Fault       : BOOL := FALSE;
    bVacSensor3_Fault       : BOOL := FALSE;

    bSpeedSensor1_Fault     : BOOL := FALSE;
    bSpeedSensor2_Fault     : BOOL := FALSE;
    bSpeedSensor3_Fault     : BOOL := FALSE;

    bTempSensor1_Fault      : BOOL := FALSE;
    bTempSensor2_Fault      : BOOL := FALSE;
    bTempSensor3_Fault      : BOOL := FALSE;

    (* State-Space Observer and Model Predictive Chuck Dynamics *)
    (* Discrete State Vector x = [theta_rad, omega_rad_s, tau_load_Nm]^T *)
    rState_Theta_rad        : REAL := 0.0;  (* Estimated chuck angular displacement [rad] *)
    rState_Omega_rads       : REAL := 0.0;  (* Estimated chuck angular velocity [rad/s] *)
    rState_Disturbance_Nm   : REAL := 0.0;  (* Estimated fluid shear drag and friction torque [Nm] *)

    (* Chuck Physical Parameters: J = 0.048 kg*m^2 (rotor + 300mm wafer), viscous B = 0.0012 Nms/rad *)
    rParam_Inertia_J        : REAL := 0.048; (* Total rotor, chuck, and liquid film rotational moment of inertia [kg*m^2] *)
    rParam_Viscous_B        : REAL := 0.0012;(* Spindle bearing and ambient gas viscous friction [N*s/rad] *)
    rSamplePeriod_s         : REAL := 0.010; (* Sample period Ts = 10 ms *)

    (* Discrete State Space Matrices for x(k+1) = Ad * x(k) + Bd * u(k) + L * (y - Cd * x) *)
    (* Ad = [1, Ts, 0; 0, 1 - (B/J)*Ts, Ts/J; 0, 0, 1] *)
    rMat_Ad11               : REAL := 1.0;
    rMat_Ad12               : REAL := 0.010;
    rMat_Ad13               : REAL := 0.0;
    rMat_Ad21               : REAL := 0.0;
    rMat_Ad22               : REAL := 0.99975; (* 1.0 - (0.0012 / 0.048) * 0.010 *)
    rMat_Ad23               : REAL := 0.20833; (* (1.0 / 0.048) * 0.010 *)
    rMat_Ad31               : REAL := 0.0;
    rMat_Ad32               : REAL := 0.0;
    rMat_Ad33               : REAL := 1.0;

    (* Bd = [0.5*Ts^2/J; Ts/J; 0] *)
    rMat_Bd1                : REAL := 0.00104;
    rMat_Bd2                : REAL := 0.20833;
    rMat_Bd3                : REAL := 0.0;

    (* Luenberger Observer Gains L = [L1; L2; L3] tuned for 5x plant pole placement *)
    rMat_L1                 : REAL := 0.15;
    rMat_L2                 : REAL := 0.45;
    rMat_L3                 : REAL := 0.08;

    (* Radial Arm Kinematic Velocity Profiling Internal Variables *)
    rArmScanStart_mm        : REAL := 5.0;   (* Inner wafer center scan boundary [mm] *)
    rArmScanEnd_mm          : REAL := 148.0; (* Outer wafer bevel clearance boundary [mm] *)
    rArmTargetSpeed_mms     : REAL := 45.0;  (* Baseline peripheral sweep velocity [mm/s] *)
    rArmComputedVel_mms     : REAL := 15.0;  (* Dynamically calculated instantaneous feed [mm/s] *)
    bArmScanDirectionOut    : BOOL := TRUE;  (* TRUE = moving outward toward bevel, FALSE = inward to center *)

    (* Timers and Filter Accumulators *)
    tStepTimer              : TON;          (* Step dwell execution timer *)
    tStepTimeLimit          : TIME := T#30S;(* Active recipe step duration setpoint *)
    tVacSettleTimer         : TON;          (* Vacuum grip confirmation timer *)
    tBrakeCheckTimer        : TON;          (* Spindle standstill confirmation timer *)
    tDegradedFaultTimer     : TON;          (* Graceful degradation persistence filter *)

    (* Vibration and Process Limit Constants *)
    rLimit_VibrationTrip_mms: REAL := 4.8;   (* Maximum allowable spindle vibration before critical abort [mm/s] *)
    rLimit_VacTrip_mbar     : REAL := -480.0;(* Minimum vacuum threshold for wafer retention confirmation [mbar] *)
    rLimit_ExhaustTrip_Pa   : REAL := -25.0; (* Minimum exhaust differential pressure before chemical lockout [Pa] *)
    rLimit_SpeedMax_rpm     : REAL := 4650.0;(* Absolute overspeed hard boundary [rpm] *)

    (* Mathematical helpers *)
    rRadiusNorm             : REAL;
    rDelta12                : REAL;
    rDelta23                : REAL;
    rDelta31                : REAL;
    rErrY                   : REAL;
    rPredOmega              : REAL;
    rTargetAccel_rads2      : REAL;
    rFeedforwardTorque_Nm   : REAL;
END_VAR

(* ==================================================================================================== *)
(*                                    CYBER-PHYSICAL CONTROL LOGIC                                      *)
(* ==================================================================================================== *)

(* === SECTION 1: 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) VOTER SUBSYSTEM === *)

(* 1.1 Chuck Vacuum 2oo3 Sensor Voting *)
rDelta12 := ABS(rChuckVac1_mbar - rChuckVac2_mbar);
rDelta23 := ABS(rChuckVac2_mbar - rChuckVac3_mbar);
rDelta31 := ABS(rChuckVac3_mbar - rChuckVac1_mbar);

bVacSensor1_Fault := FALSE;
bVacSensor2_Fault := FALSE;
bVacSensor3_Fault := FALSE;

IF (rDelta12 <= 40.0) AND (rDelta23 <= 40.0) AND (rDelta31 <= 40.0) THEN
    (* All three vacuum sensors healthy and in consensus *)
    rVotedChuckVac_mbar := (rChuckVac1_mbar + rChuckVac2_mbar + rChuckVac3_mbar) / 3.0;
ELSIF (rDelta12 <= 40.0) AND (rDelta23 > 40.0) AND (rDelta31 > 40.0) THEN
    (* Sensor 3 is divergent outlier: degrade to 1oo2 of sensors 1 and 2 *)
    bVacSensor3_Fault := TRUE;
    rVotedChuckVac_mbar := (rChuckVac1_mbar + rChuckVac2_mbar) / 2.0;
ELSIF (rDelta23 <= 40.0) AND (rDelta12 > 40.0) AND (rDelta31 > 40.0) THEN
    (* Sensor 1 is divergent outlier: degrade to 1oo2 of sensors 2 and 3 *)
    bVacSensor1_Fault := TRUE;
    rVotedChuckVac_mbar := (rChuckVac2_mbar + rChuckVac3_mbar) / 2.0;
ELSIF (rDelta31 <= 40.0) AND (rDelta12 > 40.0) AND (rDelta23 > 40.0) THEN
    (* Sensor 2 is divergent outlier: degrade to 1oo2 of sensors 1 and 3 *)
    bVacSensor2_Fault := TRUE;
    rVotedChuckVac_mbar := (rChuckVac1_mbar + rChuckVac3_mbar) / 2.0;
ELSE
    (* Total TMR disagreement across all three channels: take most conservative minimum vacuum *)
    rVotedChuckVac_mbar := MAX(rChuckVac1_mbar, MAX(rChuckVac2_mbar, rChuckVac3_mbar));
    wAlarmWord1.0 := TRUE; (* TMR_VACUUM_DISAGREEMENT_FAULT *)
END_IF;

(* 1.2 Spindle Rotary Speed 2oo3 Sensor Voting *)
rDelta12 := ABS(rChuckSpeed1_rpm - rChuckSpeed2_rpm);
rDelta23 := ABS(rChuckSpeed2_rpm - rChuckSpeed3_rpm);
rDelta31 := ABS(rChuckSpeed3_rpm - rChuckSpeed1_rpm);

bSpeedSensor1_Fault := FALSE;
bSpeedSensor2_Fault := FALSE;
bSpeedSensor3_Fault := FALSE;

IF (rDelta12 <= 55.0) AND (rDelta23 <= 55.0) AND (rDelta31 <= 55.0) THEN
    rVotedChuckSpeed_rpm := (rChuckSpeed1_rpm + rChuckSpeed2_rpm + rChuckSpeed3_rpm) / 3.0;
ELSIF (rDelta12 <= 55.0) THEN
    bSpeedSensor3_Fault := TRUE;
    rVotedChuckSpeed_rpm := (rChuckSpeed1_rpm + rChuckSpeed2_rpm) / 2.0;
ELSIF (rDelta23 <= 55.0) THEN
    bSpeedSensor1_Fault := TRUE;
    rVotedChuckSpeed_rpm := (rChuckSpeed2_rpm + rChuckSpeed3_rpm) / 2.0;
ELSIF (rDelta31 <= 55.0) THEN
    bSpeedSensor2_Fault := TRUE;
    rVotedChuckSpeed_rpm := (rChuckSpeed1_rpm + rChuckSpeed3_rpm) / 2.0;
ELSE
    rVotedChuckSpeed_rpm := MAX(rChuckSpeed1_rpm, MAX(rChuckSpeed2_rpm, rChuckSpeed3_rpm));
    wAlarmWord1.1 := TRUE; (* TMR_SPEED_DISAGREEMENT_FAULT *)
END_IF;

(* 1.3 Inline Chemical Delivery Temperature 2oo3 Sensor Voting *)
rDelta12 := ABS(rChemTemp1_degC - rChemTemp2_degC);
rDelta23 := ABS(rChemTemp2_degC - rChemTemp3_degC);
rDelta31 := ABS(rChemTemp3_degC - rChemTemp1_degC);

bTempSensor1_Fault := FALSE;
bTempSensor2_Fault := FALSE;
bTempSensor3_Fault := FALSE;

IF (rDelta12 <= 2.5) AND (rDelta23 <= 2.5) AND (rDelta31 <= 2.5) THEN
    rVotedChemTemp_degC := (rChemTemp1_degC + rChemTemp2_degC + rChemTemp3_degC) / 3.0;
ELSIF (rDelta12 <= 2.5) THEN
    bTempSensor3_Fault := TRUE;
    rVotedChemTemp_degC := (rChemTemp1_degC + rChemTemp2_degC) / 2.0;
ELSIF (rDelta23 <= 2.5) THEN
    bTempSensor1_Fault := TRUE;
    rVotedChemTemp_degC := (rChemTemp2_degC + rChemTemp3_degC) / 2.0;
ELSIF (rDelta31 <= 2.5) THEN
    bTempSensor2_Fault := TRUE;
    rVotedChemTemp_degC := (rChemTemp1_degC + rChemTemp3_degC) / 2.0;
ELSE
    rVotedChemTemp_degC := MAX(rChemTemp1_degC, MAX(rChemTemp2_degC, rChemTemp3_degC));
    wAlarmWord1.2 := TRUE; (* TMR_TEMPERATURE_DISAGREEMENT_FAULT *)
END_IF;

(* 1.4 Update Sensor Health Register Mask *)
wSensorHealthMask.0 := bVacSensor1_Fault;
wSensorHealthMask.1 := bVacSensor2_Fault;
wSensorHealthMask.2 := bVacSensor3_Fault;
wSensorHealthMask.3 := bSpeedSensor1_Fault;
wSensorHealthMask.4 := bSpeedSensor2_Fault;
wSensorHealthMask.5 := bSpeedSensor3_Fault;
wSensorHealthMask.6 := bTempSensor1_Fault;
wSensorHealthMask.7 := bTempSensor2_Fault;
wSensorHealthMask.8 := bTempSensor3_Fault;

bWarningActive := (wSensorHealthMask <> 16#0000);

(* === SECTION 2: HIGH-INTEGRITY SAFETY INTERLOCKS AND FAULT DETECTION === *)

(* 2.1 Dual-Channel Emergency Stop Interlock [SIL3 / PLe] *)
IF NOT bEmergencyStopRelayOk THEN
    wAlarmWord1.3 := TRUE; (* EMERGENCY_STOP_TRIPPED *)
END_IF;

(* 2.2 Wafer Dynamic Retention Interlock: Vacuum Loss Protection *)
(* If chuck rotates above 60 rpm and vacuum drops above -480 mbar, wafer fly-off risk exists *)
IF (rVotedChuckSpeed_rpm > 60.0) AND (rVotedChuckVac_mbar > rLimit_VacTrip_mbar) THEN
    wAlarmWord1.4 := TRUE; (* WAFER_VACUUM_LOSS_FLYOFF_RISK *)
END_IF;

(* 2.3 Chuck Spindle Dynamic Vibration Interlock *)
IF rChuckVibration_mms > rLimit_VibrationTrip_mms THEN
    wAlarmWord1.5 := TRUE; (* CHUCK_EXCESSIVE_VIBRATION_TRIP *)
END_IF;

(* 2.4 Spindle Hard Overspeed Guard *)
IF rVotedChuckSpeed_rpm > rLimit_SpeedMax_rpm THEN
    wAlarmWord1.6 := TRUE; (* CHUCK_HARD_OVERSPEED_TRIP *)
END_IF;

(* 2.5 Chemical Vapor Exhaust Differential Pressure Interlock *)
(* Chemical dispense prohibited if clean cup exhaust draft is insufficient *)
IF rChamberExhaust_Pa > rLimit_ExhaustTrip_Pa THEN
    wAlarmWord1.7 := TRUE; (* EXHAUST_PRESSURE_INSUFFICIENT_TRIP *)
END_IF;

(* 2.6 Chemical Process Temperature Excursion *)
IF rVotedChemTemp_degC > 88.0 THEN
    wAlarmWord2.0 := TRUE; (* CHEMICAL_OVERTEMPERATURE_TRIP *)
END_IF;

(* 2.7 Global Alarm Aggregation and E-Stop Routing *)
bAlarmActive := (wAlarmWord1 <> 16#0000) OR (wAlarmWord2 <> 16#0000);

IF bAlarmActive OR bAbortCycle OR (NOT bEnable) THEN
    iTargetStep := 900; (* Forced deterministic safe abort sequence *)
END_IF;

(* === SECTION 3: STATE-SPACE OBSERVER & MODEL PREDICTIVE TORQUE ESTIMATION === *)

(* Convert voted rotational speed from RPM to rad/s for state estimator *)
(* omega [rad/s] = rpm * (2*pi / 60) = rpm * 0.104719755 *)
rPredOmega := rVotedChuckSpeed_rpm * 0.104719755;

(* Innovation / Output Estimation Error: e = y - Cd * x_hat *)
rErrY := rPredOmega - rState_Omega_rads;

(* Luenberger State-Space Observer Discrete Update: x(k+1) = Ad*x(k) + Bd*u(k) + L*e(k) *)
rState_Theta_rad := rMat_Ad11 * rState_Theta_rad + rMat_Ad12 * rState_Omega_rads + rMat_L1 * rErrY;
rState_Omega_rads := rMat_Ad21 * rState_Theta_rad + rMat_Ad22 * rState_Omega_rads + rMat_Ad23 * rState_Disturbance_Nm + rMat_Bd2 * (rChuckTorqueLimit_Nm * 0.15) + rMat_L2 * rErrY;
rState_Disturbance_Nm := rMat_Ad33 * rState_Disturbance_Nm + rMat_L3 * rErrY;

(* Model Predictive Feedforward Torque Calculation based on target acceleration and fluid drag *)
IF (rChuckSpeedSetpt_rpm > rVotedChuckSpeed_rpm + 5.0) THEN
    rTargetAccel_rads2 := 125.66; (* +1200 rpm/s ramp acceleration rate [rad/s^2] *)
ELSIF (rChuckSpeedSetpt_rpm < rVotedChuckSpeed_rpm - 5.0) THEN
    rTargetAccel_rads2 := -157.08; (* -1500 rpm/s dynamic brake deceleration rate [rad/s^2] *)
ELSE
    rTargetAccel_rads2 := 0.0; (* Constant angular velocity cruise phase *)
END_IF;

(* Inertial acceleration torque + Viscous drag + Estimated liquid shear disturbance torque *)
rFeedforwardTorque_Nm := (rParam_Inertia_J * rTargetAccel_rads2) + (rParam_Viscous_B * rState_Omega_rads) + ABS(rState_Disturbance_Nm);

(* Dynamic Torque Boundary Clamping [Nm] *)
IF rFeedforwardTorque_Nm < 3.0 THEN
    rChuckTorqueLimit_Nm := 3.0;
ELSIF rFeedforwardTorque_Nm > 24.0 THEN
    rChuckTorqueLimit_Nm := 24.0;
ELSE
    rChuckTorqueLimit_Nm := rFeedforwardTorque_Nm + 2.5; (* 2.5 Nm headroom margin *)
END_IF;

(* === SECTION 4: RADIAL DISPENSE ARM INVERSE-SQUARE-ROOT VELOCITY PROFILER === *)

(* Normalize instantaneous arm radius: 300mm wafer radius = 150.0 mm *)
rRadiusNorm := MAX(rArmRadialPos_mm, 8.0) / 150.0;

(* Fluid film boundary layer residence time is maintained invariant across the wafer radius *)
(* by modulating arm linear sweep speed according to: v(r) = v_target * SQRT(1.0 / r_norm) *)
rArmComputedVel_mms := rArmTargetSpeed_mms * SQRT(1.0 / rRadiusNorm);

(* Velocity saturation guard to prevent drive servo saturation near wafer center (r -> 0) *)
IF rArmComputedVel_mms > 220.0 THEN
    rArmComputedVel_mms := 220.0;
ELSIF rArmComputedVel_mms < 8.0 THEN
    rArmComputedVel_mms := 8.0;
END_IF;

rArmVelSetpoint_mms := rArmComputedVel_mms;

(* Automatic continuous bidirectional linear sweep integration *)
IF bArmScanDirectionOut THEN
    rArmPosSetpoint_mm := rArmPosSetpoint_mm + (rArmComputedVel_mms * rSamplePeriod_s);
    IF rArmPosSetpoint_mm >= rArmScanEnd_mm THEN
        rArmPosSetpoint_mm := rArmScanEnd_mm;
        bArmScanDirectionOut := FALSE; (* Reverse motion direction toward wafer center *)
    END_IF;
ELSE
    rArmPosSetpoint_mm := rArmPosSetpoint_mm - (rArmComputedVel_mms * rSamplePeriod_s);
    IF rArmPosSetpoint_mm <= rArmScanStart_mm THEN
        rArmPosSetpoint_mm := rArmScanStart_mm;
        bArmScanDirectionOut := TRUE; (* Reverse motion direction toward wafer edge *)
    END_IF;
END_IF;

(* === SECTION 5: MULTI-STAGE SEMICONDUCTOR WET PROCESS SEQUENCER === *)

IF (iTargetStep <> 0) AND (iTargetStep <> iStep) THEN
    iStep := iTargetStep;
    iTargetStep := 0;
END_IF;

(* Step Transition Detection and Step Timer Reset *)
IF iStep <> iPrevStep THEN
    tStepTimer(IN := FALSE);
    iPrevStep := iStep;
    rCurrentStepTime_s := 0.0;
ELSE
    tStepTimer(IN := TRUE, PT := tStepTimeLimit);
    rCurrentStepTime_s := TIME_TO_REAL(tStepTimer.ET) / 1000.0;
END_IF;

CASE iStep OF

    0: (* === IDLE / STANDBY / WAFER HANDOFF PHASE === *)
        bSystemReady            := (NOT bAlarmActive) AND bEmergencyStopRelayOk AND bEnable;
        bCycleRunning           := FALSE;
        bCycleComplete          := FALSE;
        rChuckSpeedSetpt_rpm    := 0.0;
        rArmPosSetpoint_mm      := -30.0; (* Park arm at safe home maintenance cup *)
        bValveSC1_Cmd           := FALSE;
        bValveDHF_Cmd           := FALSE;
        bValveSC2_Cmd           := FALSE;
        bValveUPW_Cmd           := FALSE;
        bValveIPAVapor_Cmd      := FALSE;
        bValveChuckVac_Cmd      := FALSE;
        bValveChamberN2_Cmd     := TRUE;  (* Low-rate continuous chamber N2 purge *)
        bMegasonicEnable        := FALSE;
        rMegasonicPower_W       := 0.0;

        IF bStartCycle AND bSystemReady THEN
            bValveChuckVac_Cmd  := TRUE;  (* Engage Bernoulli vacuum clamping *)
            tStepTimeLimit      := T#3S;
            iStep               := 5;     (* Advance to vacuum verification *)
        END_IF;

    5: (* === WAFER VACUUM RETENTION VERIFICATION === *)
        bCycleRunning           := TRUE;
        bSystemReady            := FALSE;
        bValveChuckVac_Cmd      := TRUE;
        tVacSettleTimer(IN := (rVotedChuckVac_mbar <= -650.0), PT := T#500MS);

        IF tVacSettleTimer.Q THEN
            tVacSettleTimer(IN := FALSE);
            tStepTimeLimit      := T#6S;
            iStep               := 10;    (* Vacuum confirmed: proceed to Pre-Wet Rinse *)
        ELSIF tStepTimer.Q THEN
            wAlarmWord1.4       := TRUE;  (* Vacuum seal failed to achieve -650 mbar within 3.0s *)
            iStep               := 900;
        END_IF;

    10: (* === STAGE 1: ULTRA-PURE WATER (UPW) PRE-WET RINSE === *)
        (* Displaces air boundary layer and uniforms wafer surface hydrophilicity *)
        rChuckSpeedSetpt_rpm    := 500.0;
        bValveUPW_Cmd           := TRUE;
        rArmPosSetpoint_mm      := 15.0;  (* Fixed dispense position near wafer apex *)
        tStepTimeLimit          := T#8S;

        IF tStepTimer.Q THEN
            bValveUPW_Cmd       := FALSE;
            tStepTimeLimit      := T#30S;
            iStep               := 20;    (* Proceed to SC1 Clean *)
        END_IF;

    20: (* === STAGE 2: SC1 CHEMICAL ETCH & PARTICLE REMOVAL === *)
        (* Standard Clean 1 (NH4OH:H2O2:DIW 1:1:5 at 65 deg C) with radial dynamic arm scan *)
        rChuckSpeedSetpt_rpm    := 850.0;
        bValveSC1_Cmd           := TRUE;
        rArmTargetSpeed_mms     := 48.0;  (* Base velocity for inverse-square root profiler *)
        tStepTimeLimit          := T#35S;

        (* Verify chemical flow within tight window [mL/min] *)
        IF (rFlowSC1_mLmin < 1400.0) OR (rFlowSC1_mLmin > 2400.0) THEN
            wAlarmWord2.1       := TRUE;  (* SC1_FLOW_RATE_DEVIATION *)
        END_IF;

        IF tStepTimer.Q THEN
            bValveSC1_Cmd       := FALSE;
            tStepTimeLimit      := T#20S;
            iStep               := 30;    (* Proceed to Intermediate UPW Rinse *)
        END_IF;

    30: (* === STAGE 3: INTERMEDIATE HIGH-FLOW UPW RINSE === *)
        (* Neutralize and quench alkaline SC1 chemical boundary layer *)
        rChuckSpeedSetpt_rpm    := 1400.0;
        bValveUPW_Cmd           := TRUE;
        rArmTargetSpeed_mms     := 65.0;
        tStepTimeLimit          := T#22S;

        IF tStepTimer.Q THEN
            bValveUPW_Cmd       := FALSE;
            tStepTimeLimit      := T#25S;
            iStep               := 40;    (* Proceed to DHF Oxide Strip *)
        END_IF;

    40: (* === STAGE 4: DHF CHEMICAL STRIP (NATIVE OXIDE REMOVAL) === *)
        (* Dilute Hydrofluoric Acid (100:1 DHF at 22 deg C) for precise atomic-scale oxide etch *)
        rChuckSpeedSetpt_rpm    := 700.0;
        bValveDHF_Cmd           := TRUE;
        rArmTargetSpeed_mms     := 35.0;
        tStepTimeLimit          := T#28S;

        IF (rFlowDHF_mLmin < 900.0) OR (rFlowDHF_mLmin > 1800.0) THEN
            wAlarmWord2.2       := TRUE;  (* DHF_FLOW_RATE_DEVIATION *)
        END_IF;

        IF tStepTimer.Q THEN
            bValveDHF_Cmd       := FALSE;
            tStepTimeLimit      := T#25S;
            iStep               := 50;    (* Proceed to SC2 Megasonic Clean *)
        END_IF;

    50: (* === STAGE 5: SC2 ACIDIC MEGASONIC ACOUSTIC STRIP === *)
        (* Standard Clean 2 (HCl:H2O2:DIW) with 1.0 MHz Megasonic transducer cavitation *)
        rChuckSpeedSetpt_rpm    := 1100.0;
        bValveSC2_Cmd           := TRUE;
        bMegasonicEnable        := TRUE;
        rMegasonicPower_W       := 85.0;  (* 85 Watts RF power delivery *)
        rArmTargetSpeed_mms     := 52.0;
        tStepTimeLimit          := T#30S;

        IF (rFlowSC2_mLmin < 1100.0) OR (rFlowSC2_mLmin > 2100.0) THEN
            wAlarmWord2.3       := TRUE;  (* SC2_FLOW_RATE_DEVIATION *)
        END_IF;

        IF tStepTimer.Q THEN
            bValveSC2_Cmd       := FALSE;
            bMegasonicEnable    := FALSE;
            rMegasonicPower_W   := 0.0;
            tStepTimeLimit      := T#20S;
            iStep               := 60;    (* Proceed to Marangoni IPA/N2 Dewetting *)
        END_IF;

    60: (* === STAGE 6: MARANGONI SURFACE-TENSION GRADIENT DEWETTING === *)
        (* IPA vapor injected at meniscus front as UPW nozzle retracts outward from center *)
        rChuckSpeedSetpt_rpm    := 380.0; (* Low rotational velocity to prevent centrifugal droplet fling *)
        bValveUPW_Cmd           := TRUE;
        bValveIPAVapor_Cmd      := TRUE;
        rArmTargetSpeed_mms     := 6.5;   (* Controlled slow outward velocity 6.5 mm/s *)
        tStepTimeLimit          := T#22S;

        IF (rFlowIPAN2_sccm < 2500.0) THEN
            wAlarmWord2.4       := TRUE;  (* MARANGONI_CARRIER_GAS_FLOW_LOW *)
        END_IF;

        IF tStepTimer.Q THEN
            bValveUPW_Cmd       := FALSE;
            bValveIPAVapor_Cmd  := FALSE;
            rArmPosSetpoint_mm  := -30.0; (* Park arm safely into cup before spin *)
            tStepTimeLimit      := T#35S;
            iStep               := 70;    (* Proceed to High-Speed Rotational Spin-Dry *)
        END_IF;

    70: (* === STAGE 7: 4200 RPM ULTRA-HIGH-SPEED SPIN-DRY === *)
        (* Total centrifugal liquid removal and wafer dehydration under pure N2 blanket *)
        rChuckSpeedSetpt_rpm    := 4200.0;
        bValveChamberN2_Cmd     := TRUE;  (* 8000 sccm dry N2 curtain *)
        tStepTimeLimit          := T#30S;

        (* Active vibration surveillance during critical resonance crossover *)
        IF rChuckVibration_mms > 2.8 THEN
            wAlarmWord2.5       := TRUE;  (* SPIN_DRY_VIBRATION_WARNING *)
        END_IF;

        IF tStepTimer.Q THEN
            rChuckSpeedSetpt_rpm:= 0.0;   (* Initiate controlled regenerative dynamic braking *)
            tStepTimeLimit      := T#15S;
            iStep               := 80;    (* Proceed to Spindle Deceleration *)
        END_IF;

    80: (* === STAGE 8: DECELERATION AND SPINDLE STANDSTILL CONFIRMATION === *)
        rChuckSpeedSetpt_rpm    := 0.0;

        (* Wait for 2oo3 voted speed to reach true mechanical zero *)
        tBrakeCheckTimer(IN := (rVotedChuckSpeed_rpm <= 8.0), PT := T#1500MS);

        IF tBrakeCheckTimer.Q THEN
            tBrakeCheckTimer(IN := FALSE);
            bValveChuckVac_Cmd  := FALSE; (* De-energize vacuum clamp, allow wafer lift-pin rise *)
            bCycleComplete      := TRUE;
            bCycleRunning       := FALSE;
            iStep               := 0;     (* Return to Standby Ready *)
        ELSIF tStepTimer.Q THEN
            wAlarmWord1.5       := TRUE;  (* SPINDLE_BRAKE_TIMEOUT_FAULT *)
            iStep               := 900;
        END_IF;

    900: (* === STAGE 900: FAIL-SAFE SHUTDOWN & EMERGENCY ABORT SEQUENCE === *)
        (* Immediate isolation of hazardous chemicals and controlled wafer preservation *)
        bValveSC1_Cmd           := FALSE;
        bValveDHF_Cmd           := FALSE;
        bValveSC2_Cmd           := FALSE;
        bValveUPW_Cmd           := FALSE;
        bValveIPAVapor_Cmd      := FALSE;
        bMegasonicEnable        := FALSE;
        rMegasonicPower_W       := 0.0;

        (* Arm commanded to full home retraction at safe velocity *)
        rArmPosSetpoint_mm      := -35.0;
        rArmVelSetpoint_mms     := 80.0;

        (* Chuck active electric braking commanded to 0 rpm *)
        rChuckSpeedSetpt_rpm    := 0.0;
        rChuckTorqueLimit_Nm    := 24.0;  (* Maximum available regenerative braking torque *)

        (* Emergency N2 purge active to strip chemical vapors toward exhaust *)
        bValveChamberN2_Cmd     := TRUE;

        (* CRITICAL SAFETY INTERLOCK: Vacuum clamp MUST remain engaged until chuck stops *)
        IF rVotedChuckSpeed_rpm > 10.0 THEN
            bValveChuckVac_Cmd  := TRUE;  (* Prevent projectile ejection of silicon wafer *)
        ELSE
            bValveChuckVac_Cmd  := FALSE; (* Safe to unclamp once spindle is at complete standstill *)
        END_IF;

        bCycleRunning           := FALSE;
        bSystemReady            := FALSE;

        (* Return to idle upon operator clearing alarm and asserting enable *)
        IF (NOT bAlarmActive) AND (NOT bAbortCycle) AND bEnable AND (rVotedChuckSpeed_rpm <= 5.0) THEN
            iStep := 0;
        END_IF;

END_CASE;

(* === SECTION 6: SEMI E30 GEM STATUS REGISTER ENCODING === *)
wStatusWord.0 := bSystemReady;
wStatusWord.1 := bCycleRunning;
wStatusWord.2 := bCycleComplete;
wStatusWord.3 := bAlarmActive;
wStatusWord.4 := bWarningActive;
wStatusWord.5 := (iStep = 70);       (* High-Speed Spin Dry Active *)
wStatusWord.6 := bValveChuckVac_Cmd; (* Vacuum Clamp Engaged *)
wStatusWord.7 := (rVotedChuckSpeed_rpm > 50.0); (* Chuck Spindle Rotating *)
wStatusWord.8 := bMegasonicEnable;   (* Megasonic RF Active *)
wStatusWord.9 := (iStep = 20) OR (iStep = 40) OR (iStep = 50); (* Chemical Dispense Active *)
wStatusWord.10 := (iStep = 60);      (* Marangoni Dewetting Phase *)

END_FUNCTION_BLOCK
